#!/usr/bin/env bash
# Compile the committed Metal sources (python/matchedfilter/metal/*.metal) into .metallib
# files with Apple's toolchain, then restamp the Metal kernel identity. The .metal files are
# generated by slangc and committed (tools/build_spirv.py); only Apple's compiler can do this
# half, so the macOS CI job and the macOS release wheels run it. Exits nonzero, naming the
# kernel, if Apple rejects one.
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/.." && pwd)
cd "$ROOT/python/matchedfilter/metal"
xcrun -sdk macosx metal --version | head -1
ls *.metal | xargs -P 3 -I{} sh -c 'n=${1%.metal}; xcrun -sdk macosx metal -c "$1" -o "$n.air" \
  && xcrun -sdk macosx metallib "$n.air" -o "$n.metallib" && rm -f "$n.air" \
  || { echo "precompile_metal: Apple rejected $1"; exit 1; }' _ {}
echo "precompile_metal: built $(ls *.metallib | wc -l) metallib files from $(ls *.metal | wc -l) sources"
cd "$ROOT"
python3 tools/kernel_build_id.py --backend metal
